5	.no-header {
6	  $root: &;
7	  position: fixed;
8	  top: 0;
9	  left: 0;
10	  right: 0;
11	  width: 100%;
12	  height: var(--header-height);
13	  background: transparent;
14	  z-index: var(--z-index-header);
15	  overflow: visible;
16	  transition:
17	    background var(--transition-default),
18	    backdrop-filter var(--transition-default),
19	    -webkit-backdrop-filter var(--transition-default),
20	    border-color var(--transition-default),
21	    opacity var(--transition-default),
22	    transform var(--transition-default);
23	  transform: translateY(0);
24	  opacity: 1;
25	  border-bottom: 1px solid var(--clr-border-default);
26	  html.is-intro & {
27	    transform: translateY(-100%);
28	    opacity: 0;
29	    pointer-events: none;
30	  }
31	
32	  &.visual {
33	    background: var(--clr-surface-weak);
34	    backdrop-filter: blur(2px);
35	    -webkit-backdrop-filter: blur(2px);
36	  }
37	
38	  &[aria-expanded="true"] {
39	    background: var(--clr-ui-bg);
40	    #{$root}__inner {
41	      border-color: var(--clr-border-default);
42	    }
43	  }
44	
45	  &.visual[aria-expanded="true"] {
46	    border-color: var(--clr-border-default);
47	  }
48	
49	  &__inner {
50	    position: relative;
51	    z-index: calc(var(--z-index-drawer) + 1);
52	    @include flex-center();
53	    height: var(--header-height);
54	    transition: var(--transition-default);
55	    border-bottom: 1px solid transparent;
56	  }
57	
58	  &__wrap {
59	    display: flex;
60	    align-items: center;
61	    gap: var(--gutter-sm);
62	    height: var(--header-height);
63	    width: 100%;
64	  }
65	
66	  &-right {
67	    display: flex;
68	    align-items: center;
69	    gap: var(--gutter-sm);
70	  }
71	
72	  &__nav {
73	    display: flex;
74	    align-items: center;
75	    height: 100%;
76	  }
77	
78	  &__gnb {
79	    display: flex;
80	    align-items: center;
81	    gap: var(--gutter-lg);
82	  }
83	
84	  &__gnb-item {
85	    position: relative;
86	    display: flex;
87	    align-items: center;
88	    gap: var(--gutter-xs);
89	  }
90	
91	  &__gnb-link {
92	    display: inline-flex;
93	    align-items: center;
94	    color: var(--clr-text-title);
95	    font-family: var(--family-en-title);
96	    @include font("f-body-1");
97	    font-weight: 600;
98	    text-decoration: none;
99	    letter-spacing: fluid(0, 1);
100	    transition: var(--transition-fast);
101	
102	    &:hover {
103	      color: var(--clr-text-body);
104	    }
105	
106	    &.is-active {
107	      color: var(--clr-primary-300);
108	    }
109	  }
110	
111	  &__works-signboard {
112	    display: inline-flex;
113	    align-items: center;
114	    justify-content: center;
115	    margin-left: var(--gutter-2xs);
116	    padding: 0 var(--gutter-xs);
117	    border-radius: 999px;
118	    background: var(--clr-white-24);
119	    backdrop-filter: blur(6px);
120	    -webkit-backdrop-filter: blur(6px);
121	  }
122	
123	  &__works-signboard__count {
124	    display: block;
125	    @include font("f-body-3");
126	    color: var(--clr-text-title);
127	  }
128	
129	  &__container {
130	    display: flex;
131	    justify-content: space-between;
132	    align-items: center;
133	    height: var(--header-height);
134	    width: 100%;
135	    padding: 0 var(--gutter-container);
136	  }
137	
138	  &__logo {
139	    @include flex-center();
140	    svg {
141	      display: block;
142	      height: auto;
143	      width: fluid(140, 180);
144	    }
145	  }
146	
147	  &__action {
148	    @include flex-center();
149	    gap: var(--gutter-sm);
150	  }
151	
152	  &__menu-btn {
153	    @include flex-center();
154	    width: fluid(36, 44);
155	    height: fluid(36, 44);
156	    padding: 0 !important;
157	    color: var(--clr-text-title);
158	    cursor: pointer;
159	    border: 1px solid var(--clr-border-default);
160	    border-radius: var(--scrollbar-radius);
161	    transition: var(--transition-fast);
162	
163	    .no-corner-btn__icon {
164	      svg {
165	        width: fluid(14, 20);
166	        height: fluid(14, 20);
167	        transition: transform var(--transition-fast);
168	      }
169	    }
170	
171	    &[aria-expanded="true"] .no-corner-btn__icon svg,
172	    &:hover .no-corner-btn__icon svg {
173	      transform: rotate(45deg);
174	    }
175	
176	    &:hover .no-corner-btn__icon svg {
177	      width: fluid(16, 20);
178	      height: fluid(16, 20);
179	    }
180	  }
181	}
